<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans,sans-serif;direction:rtl}h1{text-align:center}table{width:100%;border-collapse:collapse}td{border:1px solid #777;padding:8px}.l{background:#eee}</style></head><body><h1>نموذج شراء الخدمة الصحية</h1><table><tr><td class="l">الاسم</td><td>{{ $record->name }}</td></tr><tr><td class="l">رقم الهوية</td><td>{{ $record->id_number }}</td></tr><tr><td class="l">مكان الميلاد</td><td>{{ $record->birth_place }}</td></tr><tr><td class="l">تاريخ الميلاد</td><td>{{ is_numeric($record->birth_date)?date('Y-m-d',(int)$record->birth_date):$record->birth_date }}</td></tr><tr><td class="l">اسم المستفيد</td><td>{{ $record->beneficiary_name }}</td></tr><tr><td class="l">حالة التحقق</td><td>{{ [0=>'معلق',1=>'صحيح',2=>'غير صحيح'][$record->verified] ?? $record->verified }}</td></tr></table></body></html>
